def digits_to_int(digits: list) -> int:
    """ Convert list of digits into integer.
    If the result is negative, return 0.
    Assume there are no leading zeros except for 0, e.g. [1] must return 1 not 01.
    >>> digits_to_int([1, 2, 3])
    123
