def dec_to_bin(dec: float) -> int:
    """ Return binary string representation of floating point number as binary integer
    >>> dec_to_bin(0.7)
    1111010
    >>> dec_to_bin(0.6666)
    1010101
    """
    binary = ''
    for digit in str(truncate_number(dec)):
