def max_parens(paren_string: str) -> int:
    """ Compute maximum number of nesting for an individual group of parentheses."""
    parens = 0
    parens_max = 0
    parens_level = 0
    paren_string = paren_string.strip()
    paren_string = paren_string.replace('(', '')
    paren_string = paren_string.replace(')', '')
    paren_string = paren_string.split(' ')
    for paren in paren_string:
        paren = paren.strip()
        if paren == '':
            continue
        elif paren == '(':
            paren_level = paren_level + 1
            parens = paren_level
        elif paren == ')':
            if paren_level == 0:
                continue
            else:
                parens = parens_level
                parens_level -= 1
    if parens > parens_max:
        parens_max = parens
    return parens_max

