def max_depth_group(paren_string: str) -> int:
    """Return the maximum depth of grouping (i.e. parenthesis) in the given input.
    E.g. (()()) has maximum two levels of nesting while ((())) has three."""

    counter = 0
    for i in range(len(paren_string)):
        if paren_string[i] == "(":
            counter += 1
        elif paren_string[i] == ")":
            counter -= 1
        elif counter == 0:
            return counter + 1
    return 0


